#!/usr/bin/env bash
# GSZ step149 — drag-to-reorder plans in the product editor. Adds a drag handle
# per plan row + native DnD within #plans; order persists on save (sort=position).
# Patches views/admin/product_edit.ejs. No migration. Idempotent; robust check.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step149-$TS"; TMP=$(mktemp -d)
FILES=(views/admin/product_edit.ejs)
echo "==> step149: drag-reorder plans"
mkdir -p "$BK/views/admin"; for f in "${FILES[@]}"; do cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo "==> applying"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node -e "const ejs=require('$GSZ/node_modules/ejs');ejs.compile(require('fs').readFileSync('$GSZ/views/admin/product_edit.ejs','utf8'),{filename:'p'});console.log('    ejs ok')"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] && echo "    homepage 200: OK (after ${i}s)" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step149 OK ✅  In a product's editor, drag the ⠿ handle on any plan to reorder; the order sticks when you Save."
